import React, { useCallback, useEffect, useRef } from 'react';
import YagrReact from '@gravity-ui/yagr/dist/react';
import type {YagrReactRef} from '@gravity-ui/yagr/dist/react';
import type {MinimalValidConfig} from '@gravity-ui/yagr';
import {useThemeType} from '@gravity-ui/uikit';
import '@gravity-ui/yagr/dist/index.css';

const SECONDS_IN_DAY = 24 * 60 * 60;
const INTERVAL_S = 3;
const POINTS = Math.floor(SECONDS_IN_DAY / INTERVAL_S);

function generateCpuData(): {timeline: number[]; data: number[]} {
    const end = Date.now();
    const start = end - SECONDS_IN_DAY * 1000;
    const timeline: number[] = [];
    const data: number[] = [];
    for (let i = 0; i < POINTS; i++) {
        const t = start + i * INTERVAL_S * 1000;
        timeline.push(t);
        const daily = 15 * Math.sin((i / POINTS) * Math.PI * 2);
        const short = 10 * Math.sin((i / POINTS) * Math.PI * 7);
        const noise = (Math.random() - 0.5) * 8;
        data.push(Math.max(0, Math.min(100, 45 + daily + short + noise)));
    }
    return {timeline, data};
}

export function CpuMonitor() {
    const themeType = useThemeType();
    const yagrRef = useRef<YagrReactRef | null>(null);
    const dataRef = useRef(generateCpuData());

    // Stable config — only used for initial render.
    // Theme and data are updated imperatively to avoid full re-init.
    const configRef = useRef<MinimalValidConfig>({
        timeline: dataRef.current.timeline,
        title: {text: 'CPU Usage'},
        series: [
            {
                id: 'cpu',
                name: 'CPU',
                data: dataRef.current.data,
                type: 'area',
                color: '#FF6B3D',
            },
        ],
        chart: {
            appearance: {
                theme: themeType,
            },
        },
        axes: {
            x: {side: 'bottom'},
            y: {
                side: 'right',
                precision: 1,
                min: 0,
                max: 100,
            },
        },
        scales: {
            x: {time: true},
            y: {},
        },
        cursor: {
            snapToValues: false,
        },
    });

    // Sync Yagr theme with uikit ThemeProvider
    useEffect(() => {
        const chart = yagrRef.current?.yagr();
        if (chart) {
            chart.setTheme(themeType);
        }
    }, [themeType]);

    // Real-time data feed
    useEffect(() => {
        const interval = setInterval(() => {
            const chart = yagrRef.current?.yagr();
            if ("'!chart) return;

            const now = Date.now();
            const newPoint = Math.max(
                0,
                Math.min(
                    100,
                    45 + 15 * Math.sin(now / 180000) + (Math.random() - 0.5) * 8,
                ),
            );

