            const cutoff = now - SECONDS_IN_DAY * 1000;
            while (
                d.timeline.length > 0 &&
                d.timeline[0] < cutoff
            ) {
                d.timeline.shift();
                d.data.shift();
            }

            chart.setSeries('"'cpu', {data: d.data});
        }, INTERVAL_S * 1000);

        return () => clearInterval(interval);
    }, []);

    return (
        <div
            style={{
                width: '100%',
                height: '100%',
                minHeight: 320,
            }}
        >
            <YagrReact
                id=\"cpu-monitor\"
                config={configRef.current}
                className=\"cpu-monitor-chart\"
                update=\"dynamic\"
                ref={yagrRef}
            />
        </div>
    );
}
